const MODES = [
  { mode: 'walk', name: 'Walking', color: '#73BF69' },
  { mode: 'bike', name: 'Cycling', color: '#FADE2A' },
  { mode: 'bus', name: 'Bus', color: '#FF9830' },
  { mode: 'car', name: 'Car and taxi', color: '#F2495C' },
  { mode: 'subway', name: 'Subway', color: '#5794F2' },
  { mode: 'train', name: 'Train', color: '#B877D9' },
  { mode: 'other', name: 'Plane, boat, motorbike', color: '#8AB8FF' },
  { mode: '', name: 'Not labelled', color: '#8E8E8E' },
];

// Trips a month, stacked by mode, on a time axis; modes in the dashboard's
// colours, the unlabelled ones last, in grey.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const months = column('month').map(Number);
const modes = column('mode');
const trips = column('trips').map(Number);

const series = MODES.map((m) => ({
  name: m.name,
  type: 'bar',
  stack: 'trips',
  itemStyle: { color: m.color },
  barMaxWidth: 14,
  data: months.flatMap((t, i) => (modes[i] === m.mode ? [[t, trips[i]]] : [])),
})).filter((s) => s.data.length > 0);

return {
  backgroundColor: 'transparent',
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 12, type: 'scroll' },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: { type: 'time', axisLabel: { color: muted }, axisLine: { lineStyle: { color: theme.colors.border.medium } } },
  yAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series,
};

// Fixes by the seconds since the previous one, in the bins build.sql made; the
// bins past five minutes, where a trip is split, in the warning colour.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const LABELS = ['≤ 1 s', '2 s', '3–5 s', '6–10 s', '11–60 s', '1–5 min', '5–60 min', '> 1 h'];
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const bins = column('bin').map(Number);
const fixes = column('fixes').map(Number);
const total = fixes.reduce((a, b) => a + b, 0) || 1;
const data = bins.map((b, i) => ({
  value: fixes[i],
  itemStyle: { color: b >= 7 ? '#F2495C' : b >= 5 ? '#FF9830' : '#5794F2' },
}));

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => `${items[0].name}: <b>${items[0].value.toLocaleString()}</b> fixes, ${(100 * items[0].value / total).toFixed(1)} %`,
  },
  grid: { left: 8, right: 16, top: 16, bottom: 8, containLabel: true },
  xAxis: { type: 'category', data: bins.map((b) => LABELS[b - 1]), axisLabel: { color: muted },
           axisLine: { lineStyle: { color: theme.colors.border.medium } } },
  yAxis: { type: 'log', min: 1000, axisLabel: { color: muted, formatter: (v) => (v >= 1e6 ? v / 1e6 + ' M' : v / 1e3 + ' k') },
           splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series: [{ type: 'bar', data, barWidth: '60%',
             label: { show: true, position: 'top', color: muted, formatter: (p) => (100 * p.value / total).toFixed(1) + ' %' } }],
};

// The cleaning steps, top to bottom: fixes left as bars, labelled with the
// trips left where the step counts them.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const what = column('what');
const fixes = column('fixes').map(Number);
const trips = column('trips').map((v) => (v === null || v === undefined ? null : Number(v)));
const millions = (v) => (v / 1e6).toFixed(2) + ' M';

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const prev = i > 0 ? fixes[i - 1] - fixes[i] : 0;
      return `<b>${what[i]}</b><br/>${fixes[i].toLocaleString()} fixes` +
        (prev > 0 ? ` (${prev.toLocaleString()} fewer)` : '') +
        (trips[i] !== null ? `<br/>${trips[i].toLocaleString()} trips` : '');
    },
  },
  grid: { left: 8, right: 16, top: 8, bottom: 8, containLabel: true },
  yAxis: { type: 'category', inverse: true, data: what, axisLabel: { color: muted, width: 190, overflow: 'truncate' },
           axisLine: { lineStyle: { color: theme.colors.border.medium } } },
  xAxis: { type: 'value', min: 0, axisLabel: { color: muted, formatter: millions }, splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series: [
    { name: 'Fixes', type: 'bar', data: fixes, itemStyle: { color: '#5794F2' }, barWidth: '55%',
      label: { show: true, position: 'insideRight', color: '#fff',
               formatter: (p) => millions(p.value) + (trips[p.dataIndex] !== null ? ` · ${trips[p.dataIndex].toLocaleString()} trips` : '') } },
  ],
};

const MODES = [
  { mode: 'walk', name: 'Walking', color: '#73BF69' },
  { mode: 'bike', name: 'Cycling', color: '#FADE2A' },
  { mode: 'bus', name: 'Bus', color: '#FF9830' },
  { mode: 'car', name: 'Car and taxi', color: '#F2495C' },
  { mode: 'subway', name: 'Subway', color: '#5794F2' },
  { mode: 'train', name: 'Train', color: '#B877D9' },
  { mode: 'other', name: 'Plane, boat, motorbike', color: '#8AB8FF' },
  { mode: '', name: 'Not labelled', color: '#8E8E8E' },
];

// Trips by the hour they start, Beijing time, each mode as a share of its own
// trips so that walking and the train read on one scale.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const modes = column('mode');
const hours = column('hour').map(Number);
const trips = column('trips').map(Number);
const HOURS = Array.from({ length: 24 }, (_, h) => String(h).padStart(2, '0'));

const series = MODES.filter((m) => m.mode !== 'other').map((m) => {
  const raw = new Array(24).fill(0);
  modes.forEach((mode, i) => { if (mode === m.mode) raw[hours[i]] += trips[i]; });
  const total = raw.reduce((a, b) => a + b, 0);
  return { name: m.name, type: 'line', smooth: true, showSymbol: false, itemStyle: { color: m.color },
           lineStyle: { width: m.mode === '' ? 1.5 : 2, type: m.mode === '' ? 'dashed' : 'solid' },
           data: total ? raw.map((v) => (100 * v) / total) : [] };
}).filter((s) => s.data.length > 0);

return {
  backgroundColor: 'transparent',
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 12, type: 'scroll' },
  tooltip: { trigger: 'axis', valueFormatter: (v) => v.toFixed(1) + ' %' },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: { type: 'category', data: HOURS, boundaryGap: false, axisLabel: { color: muted } },
  yAxis: { type: 'value', axisLabel: { color: muted, formatter: '{value} %' }, splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series,
};

const MODES = [
  { mode: 'walk', name: 'Walking', color: '#73BF69' },
  { mode: 'bike', name: 'Cycling', color: '#FADE2A' },
  { mode: 'bus', name: 'Bus', color: '#FF9830' },
  { mode: 'car', name: 'Car and taxi', color: '#F2495C' },
  { mode: 'subway', name: 'Subway', color: '#5794F2' },
  { mode: 'train', name: 'Train', color: '#B877D9' },
  { mode: 'other', name: 'Plane, boat, motorbike', color: '#8AB8FF' },
  { mode: '', name: 'Not labelled', color: '#8E8E8E' },
];

// One line per labelled mode: the share of its fixes in each 2 km/h bin, up
// to 120 km/h; unlabelled fixes left out.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const modes = column('mode');
const kmh = column('kmh').map(Number);
const fixes = column('fixes').map(Number);

const series = MODES.filter((m) => m.mode !== '' && m.mode !== 'other').map((m) => {
  const rows = kmh.flatMap((k, i) => (modes[i] === m.mode ? [[k, fixes[i]]] : []));
  const total = rows.reduce((a, r) => a + r[1], 0) || 1;
  return {
    name: m.name, type: 'line', smooth: true, showSymbol: false, itemStyle: { color: m.color }, lineStyle: { width: 2 },
    data: rows.filter((r) => r[0] <= 120).map((r) => [r[0] + 1, (100 * r[1]) / total]),
  };
}).filter((s) => s.data.length > 0);

return {
  backgroundColor: 'transparent',
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 12, type: 'scroll' },
  tooltip: { trigger: 'axis', valueFormatter: (v) => v.toFixed(1) + ' %' },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: { type: 'value', min: 0, max: 120, name: 'km/h', nameLocation: 'end', nameTextStyle: { color: muted },
           axisLabel: { color: muted }, splitLine: { show: false } },
  yAxis: { type: 'value', axisLabel: { color: muted, formatter: '{value} %' }, splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series,
};

// Stops by duration, in doubling bins from five minutes, dwell and pause side
// by side.
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const LABELS = ['5–10 min', '10–20', '20–40', '40–80', '80–160', '2.7–5.3 h', '5.3–10.7 h', '> 10.7 h'];
const frame = context.panel.data.series[0];
const column = (name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const kinds = column('kind');
const bins = column('bin').map(Number);
const stops = column('stops').map(Number);
const of = (kind) => LABELS.map((_, b) => kinds.reduce((a, k, i) => a + (k === kind && bins[i] === b ? stops[i] : 0), 0));

return {
  backgroundColor: 'transparent',
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 12 },
  tooltip: { trigger: 'axis', axisPointer: { type: 'shadow' } },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: { type: 'category', data: LABELS, axisLabel: { color: muted, interval: 0, rotate: 30 } },
  yAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series: [
    { name: 'Dwell, inside a trip', type: 'bar', data: of('dwell'), itemStyle: { color: '#4cc9f0' } },
    { name: 'Pause, between trips', type: 'bar', data: of('pause'), itemStyle: { color: '#f72585' } },
  ],
};

const MODES = [
  { mode: 'walk', name: 'Walking', color: '#73BF69' },
  { mode: 'bike', name: 'Cycling', color: '#FADE2A' },
  { mode: 'bus', name: 'Bus', color: '#FF9830' },
  { mode: 'car', name: 'Car and taxi', color: '#F2495C' },
  { mode: 'subway', name: 'Subway', color: '#5794F2' },
  { mode: 'train', name: 'Train', color: '#B877D9' },
  { mode: 'other', name: 'Plane, boat, motorbike', color: '#8AB8FF' },
  { mode: '', name: 'Not labelled', color: '#8E8E8E' },
];

// The trip's speed over time, one series per mode so the line takes the
// mode's colour where the user labelled it; stops as shaded spans; the map's
// clock, while it plays, as a line across (its query re-runs on t_to).
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const series0 = context.panel.data.series[0];
const series1 = context.panel.data.series[1];
const column = (frame, name) => Array.from(frame?.fields.find((f) => f.name === name)?.values ?? []);
const times = column(series0, 'time').map(Number);
const kmh = column(series0, 'kmh').map(Number);
const modes = column(series0, 'mode');
const stopsFrom = column(series1, 't0').map(Number);
const stopsMin = column(series1, 'minutes').map(Number);
const BEIJING = 8 * 3600 * 1000;
const at = column(context.panel.data.series[2], 'at').map(Number).find(Number.isFinite);

const series = MODES.map((m) => ({
  name: m.name, type: 'line', showSymbol: false, connectNulls: false, itemStyle: { color: m.color }, lineStyle: { width: 1.5 },
  // A point either side of a change of mode, so the line has no gaps.
  data: times.map((t, i) => [t + BEIJING,
    modes[i] === m.mode || modes[i - 1] === m.mode ? kmh[i] : null]),
})).filter((s) => s.data.some((d) => d[1] !== null));
if (series.length) {
  series[0].markArea = {
    silent: true, itemStyle: { color: 'rgba(255, 255, 255, 0.08)' },
    data: stopsFrom.map((t, i) => [{ xAxis: t + BEIJING }, { xAxis: t + BEIJING + stopsMin[i] * 60000 }]),
  };
  if (at !== undefined && times.length && at >= times[0] && at <= times[times.length - 1]) {
    series[0].markLine = {
      silent: true, symbol: 'none', label: { show: false },
      lineStyle: { color: theme.colors.text.primary, type: 'solid', width: 1 },
      data: [{ xAxis: at + BEIJING }],
    };
  }
}

return {
  backgroundColor: 'transparent',
  legend: { top: 0, textStyle: { color: muted }, itemWidth: 12 },
  tooltip: { trigger: 'axis', valueFormatter: (v) => (v === null || v === undefined ? '–' : v.toFixed(1) + ' km/h') },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  xAxis: { type: 'time', axisLabel: { color: muted, formatter: '{HH}:{mm}' } },
  yAxis: { type: 'value', name: 'km/h', nameTextStyle: { color: muted }, axisLabel: { color: muted },
           splitLine: { lineStyle: { color: theme.colors.border.weak } } },
  series,
};
